{"id":"friday_review","schedule":"0 9 * * 5","description":"Combined Friday review: lists applications with 'waiting' status for more than 10 days and shows the full applications by status board.","steps":"-- Step 1: Fetch overdue waiting applications
-- Overdue waiting applications (waiting > 10 days)
LET overdue_waiting := SELECT company, role, applied, status FROM applications WHERE status = 'waiting' AND applied < date('now', '-10 days');

-- Step 2: Fetch full applications by status for the board
LET applications_board := SELECT status, COUNT(*) as count FROM applications GROUP BY status;

-- Output overdue waiting applications
overdue_waiting;

-- Output applications by status board
applications_board;"}

